param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks")
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop";$out=Join-Path $BenchmarkRepo "reports\v0.23.0";if(-not(Test-Path -LiteralPath $out)){New-Item -ItemType Directory -Path $out -Force|Out-Null};$roots=@("catalog\global","schemas","templates",".github\workflows");$rows=New-Object System.Collections.Generic.List[object];foreach($relativeRoot in $roots){$root=Join-Path $BenchmarkRepo $relativeRoot;if(Test-Path -LiteralPath $root){foreach($f in @(Get-ChildItem -LiteralPath $root -Recurse -File|Sort-Object FullName)){if($f.FullName -match "v0\.23\.0|schema|template|workflow|\.yml$"){$rows.Add([pscustomobject]@{path=$f.FullName.Substring($BenchmarkRepo.Length).TrimStart([char]92);sha256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash;bytes=$f.Length})}}}};$rows.ToArray()|Export-Csv -LiteralPath (Join-Path $out "RELEASE-FILE-MANIFEST-v0.23.0.csv") -NoTypeInformation -Encoding UTF8;Write-Host("RELEASE_MANIFEST_FILES|"+$rows.Count)
